INSERT INTO public.programs (id, title, subtitle, badge, grades, icon, description, subjects, key_features, career_paths, sort_order, status) VALUES
('secondary', 'Secondary School Section', 'Standards 8th, 9th & 10th (S.S.C.)', 'Foundation & Excellence', 'Std 8 to 10', 'BookOpen', 'A comprehensive curriculum designed to develop deep conceptual understanding, strong analytical thinking, ethical values, and multilingual fluency in Gujarati, English, and Hindi.', '["Mathematics & Logical Reasoning", "Science & Technology", "Social Studies & Civics", "Gujarati (First/Second Language)", "English Language & Literature", "Hindi & Sanskrit Foundations", "Computer Literacy & Environmental Studies", "Physical Education & Yoga"]'::jsonb, '["100% Board preparation with regular unit tests and mock exams.", "Specialized remedial sessions for slow learners and enrichment for high achievers.", "Interactive science lab practicals starting from Std 8th.", "Active participation in Scout & Guide and inter-school competitions."]'::jsonb, '["Higher Secondary Science (Group A/B)", "Commerce & Economics", "Arts & Humanities", "Diploma Engineering / Polytechnic"]'::jsonb, 1, 'published'),
('science', 'Higher Secondary Science Stream', 'Standards 11th & 12th (H.S.C. Science)', 'Premium STEM Stream', 'Std 11 & 12', 'Atom', 'An intensive, experiment-driven pre-university science track with specialized Group A (Engineering / Mathematics) and Group B (Medical / Biology) preparing students for competitive entrance exams.', '["Advanced Physics (Theory + Lab)", "Inorganic, Organic & Physical Chemistry (Lab)", "Biology / Life Sciences (Group B)", "Higher Mathematics (Group A)", "English Higher Level", "Computer Science & Informatics", "GUJCET, NEET & JEE Foundation Coaching"]'::jsonb, '["Fully equipped Physics, Chemistry, and Biology labs with individual workstation kits.", "Experienced senior postgraduate faculty with decades of proven board results.", "Integrated problem-solving modules for GUJCET, JEE Main, and NEET-UG.", "Regular guest lectures by medical doctors, research scientists, and IIT/NIT alumni."]'::jsonb, '["Medicine (MBBS, BDS, BHMS, BAMS)", "Engineering (CSE, AI/ML, Mechanical, Civil)", "Pharmacy & Biotechnology", "Pure Research & Data Science"]'::jsonb, 2, 'published'),
('general-vocational', 'General, Commerce & Vocational Stream', 'Standards 11th & 12th (H.S.C. General)', 'Practical Life Skills', 'Std 11 & 12', 'Briefcase', 'A dynamic stream combining rigorous commercial and humanities knowledge with real-world practical vocational training in Home Science for girls and Electrical/Technical workshops for boys.', '["Accountancy & Book-Keeping", "Economics & Financial Literacy", "Organization of Commerce & Management", "Statistics & Commercial Math", "Home Science (Food, Nutrition, Child Care & Textiles)", "Electrical Technology & Electronics Workshop", "English & Gujarati Literature"]'::jsonb, '["Home Science Lab practicals for nutrition, culinary science, interior planning, and entrepreneurship.", "Hands-on Electrical Workshop where boys learn circuitry, domestic appliances repair, and wiring standards.", "Stock market fundamentals, accounting software exposure (Tally/Excel), and business planning.", "Strong track record in university commerce degrees and self-employment ventures."]'::jsonb, '["Chartered Accountancy (CA / CS / CMA)", "Business Administration (BBA / MBA)", "Banking & Civil Services (UPSC/GPSC)", "Interior Design, Nutrition & Technical Entrepreneurship"]'::jsonb, 3, 'published'),
('cocurricular', 'Co-Curricular & Leadership Wings', 'Character Building, NSS & Bharat Scouts', 'Holistic Development', 'All Grades', 'Users', 'Beyond textbook learning, SKM nurtures disciplined leaders through active Bharat Scouts and Guides, National Service Scheme (NSS), sports championships, and cultural arts.', '["Bharat Scouts & Guides Troop", "National Service Scheme (NSS) Community Camps", "Elocution, Debate & Quiz Society", "Annual District Sports & Athletics Meet", "Eco-Club & Tree Plantation Mission", "Disaster Management & First-Aid Training"]'::jsonb, '["Governor Award winning Scout & Guide commanders from SKM High School.", "Annual rural immersion camps promoting hygiene, literacy, and environmental care.", "Inter-house sports tournaments in Cricket, Volleyball, Badminton, and Kabaddi.", "Cultural celebrations including Republic Day, Independence Day, and Annual Prize Day."]'::jsonb, '["Defense & Police Services", "Public Administration", "Sports Coaching", "Community Leadership"]'::jsonb, 4, 'published')
INSERT INTO public.facilities (id, title, subtitle, tag, stats, description, features, icon, image_url, sort_order, status) VALUES
('computer-lab', 'A.N. Musa Modern Computer Centre', 'High-Speed LAN & Digital Literacy Hub', 'Digital Learning', '80+ Workstations | Gigabit Optical Fiber', 'Established with the support of community patrons, the A.N. Musa Computer Centre is equipped with modern high-performance desktop computers, uninterrupted power backup, high-speed fiber broadband, and interactive presentation screens for digital learning and coding.', '["Dedicated LAN network connecting all systems for collaborative programming.", "Licensed educational software, Python, Scratch, Office suites, and web design tools.", "Digital literacy curriculum starting from secondary classes.", "Fully air-conditioned, ergonomically designed workstation layout."]'::jsonb, 'Monitor', '/images/computer.jpg', 1, 'published'),
('library', 'Adarsh Public & School Central Library', 'Treasury of Knowledge and Research', 'Knowledge Vault', '1,400+ Volumes | 20+ Periodicals & Journals', 'A sanctuary for avid readers and researchers. The Adarsh Public Library houses rich collections of Gujarati literature, world classics, encyclopedia series, NCERT reference books, and competitive exam preparation material for GPSC/UPSC/NEET.', '["Over 1,400 cataloged books covering science, history, philosophy, and competitive exams.", "Quiet, well-ventilated reading hall with dedicated study cubicles.", "Daily national and regional newspapers in Gujarati, English, and Hindi.", "Digital index system for rapid book search and borrowing management."]'::jsonb, 'Library', '/images/library.jpg', 2, 'published'),
('science-labs', 'Advanced Science & Physics Laboratories', 'Physics, Chemistry & Life Science Practical Labs', 'STEM Practical', '3 Dedicated Labs | Individual Workstations', 'Equipped to meet and exceed GSEB and national STEM standards, our science laboratories provide students with experiential learning opportunities. Calibrated apparatus, optical benches, analytical balances, and safety-certified chemical reagent stations ensure hands-on mastery.', '["Separate state-of-the-art labs for Physics, Chemistry, and Biology.", "Safety emergency showers, eye-wash stations, and chemical fume exhaust systems.", "High-resolution compound microscopes and prepared botanical/zoological specimens.", "Teacher demonstration bench equipped with digital projection."]'::jsonb, 'FlaskConical', '/images/physics.jpg', 3, 'published'),
('home-science-lab', 'Home Science & Practical Workshop Wing', 'Vocational Life-Skills Training Center', 'Vocational Skill', 'Dedicated Cooking Stations & Sewing Units', 'Established in the late 1980s and continuously upgraded, our Home Science lab provides hands-on culinary science, dietetics, nutrition calculation, garment design, and household management practicals for girl students.', '["Modern kitchen stations with gas piping, ovens, and food processing equipment.", "Fabric design and stitching machines for vocational tailoring.", "Dietary planning and child development laboratory modules.", "Practical demonstration areas for healthy cooking and preservation."]'::jsonb, 'Utensils', 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?auto=format&fit=crop&w=1000&q=80', 4, 'published'),
('sports-campus', 'Sports Grounds & Campus Amenities', 'Spacious Playfields & Clean Water Tube-Well Facility', 'Health & Wellness', 'Full-Sized Grounds | 24/7 RO Purified Water', 'Physical vigor and campus well-being are central to SKM values. Our sprawling grounds accommodate cricket pitches, volleyball courts, running tracks, and open-air assembly pavilions. Supported by our deep-bore tube-well and RO purification systems.', '["Spacious sports playground for football, cricket, volleyball, and kabaddi.", "Dedicated drinking water tube-well facility with advanced RO filtration systems.", "Lush green tree-lined walkways and open-air assembly ground.", "Modern clean washroom facilities with continuous running water."]'::jsonb, 'Trophy', '/images/playground.jpg', 5, 'published'),
('board-center', 'Official GSEB Board Examination Hub', 'State Board Certified Examination & Assessment Center', 'Institutional Prestige', '100% CCTV Monitored | 600+ Seating Capacity', 'SKM High School proudly serves as a designated, high-security GSEB Board Examination Center for Banaskantha district. Featuring comprehensive CCTV surveillance, soundproof testing halls, and biometric authentication protocols.', '["GSEB accredited testing facility with high-definition CCTV recording.", "Dedicated strong-room with double-lock security protocols.", "Capacity to host over 600 candidates simultaneously with comfortable benching.", "Centrally located with easy highway access from Kanodar and neighboring towns."]'::jsonb, 'ShieldCheck', '/images/building.jpg', 6, 'published')
INSERT INTO public.milestones (id, year, period, title, category, highlight, description, details, icon_name, image_url, sort_order, status) VALUES
('m1', '1956', 'May 28, 1956', 'Establishment of Sarvoday Kelavani Mandal & Humble Beginnings', 'founding', 'Foundation Stone of Educational Transformation in North Gujarat', 'Sarvoday Kelavani Mandal was founded by visionary community elders in Kanodar. In an inspiring act of selflessness, primary classes commenced in the home of Late Shri Mamjibhai Alimad Mukhi with a mission to bring formal education to every child.', '["Founded under the visionary leadership of Sarvoday Kelavani Mandal trustees.", "Classes inaugurated in the residence of Late Shri Mamjibhai Alimad Mukhi.", "Began with dedicated volunteer teachers and a fervent community spirit to eradicate educational backwardness."]'::jsonb, 'GraduationCap', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=800&q=80', 1, 'published'),
('m2', '1959 - 1960', '1959 – 1960', 'School Campus Construction & First S.S.C. Graduating Batch', 'expansion', 'Permanent Campus & First Historic Matriculation Batch', 'A permanent, sprawling school building was constructed through collective community philanthropy. The S.S.C. (Secondary School Certificate) class was officially started, graduating its very first matriculation cohort with flying colors.', '["Construction of dedicated brick-and-mortar classrooms, administrative wing, and central courtyard.", "Official recognition from the State Department of Education.", "Celebration of Kanodar’s first native batch of high school graduates who went on to become doctors, engineers, and teachers."]'::jsonb, 'Building', '/images/building.jpg', 2, 'published'),
('m3', '1976', '1976', 'Commencement of Higher Secondary Section (H.S.C. 10+2)', 'stream', 'Pioneering 10+2 Higher Secondary Education in the Region', 'Meeting the surging academic aspirations of students from Kanodar and surrounding villages, the Higher Secondary Section (Std 11th & 12th) was launched, creating a seamless pathway into college and professional careers.', '["Introduced advanced higher secondary pedagogy under the 10+2 education system.", "Expanded library and lecture halls to accommodate higher secondary scholars.", "Attracted motivated students across Banaskantha district."]'::jsonb, 'Award', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=800&q=80', 3, 'published'),
('m4', '1987 - 1989', '1987 – 1989', 'Vocational Empowerment: Home Science & Electrical Labs', 'expansion', 'Life-Skills & Practical Vocational Workshop Integration', 'Recognizing the importance of hands-on skills, the school introduced specialized Home Science curriculum for female students and Electrical/Technical workshops for male students, backed by a custom-built Home Science practical laboratory.', '["Built a dedicated Home Science Laboratory with modern culinary, tailoring, and nutrition stations for girl students.", "Established Electrical Gadgets and Electronics practical workshops for vocational self-reliance.", "Created career readiness and entrepreneurial foundations for both girls and boys."]'::jsonb, 'Wrench', '/images/physics.jpg', 4, 'published'),
('m5', '1995 - 1997', '1995 – 1997', 'Dawoodi Bohra Welfare Trust, R.K. Palasara Pariwar & Science Stream', 'stream', 'Launch of Science Stream & A.N. Musa Computer Centre', 'A watershed era marked by generous philanthropic support from the Dawoodi Bohra Welfare Trust and R.K. Palasara Pariwar. The school established the elite Higher Secondary Science Stream and founded the state-of-the-art A.N. Musa Computer Centre.', '["Inauguration of the prestigious A.N. Musa Computer Centre providing IT literacy.", "Formal launch of Higher Secondary Science Stream with specialized Physics, Chemistry, and Biology laboratories.", "Generous funding and infrastructural grants from Dawoodi Bohra Welfare Trust and R.K. Palasara Pariwar."]'::jsonb, 'Cpu', '/images/computer.jpg', 5, 'published'),
('m6', '2004 - Present', '2004 – Present Day', 'Digital High-Tech Labs, Smart Campus & Board Assessment Hub', 'modernization', 'Futuristic Digital Classrooms & Regional Assessment Center', 'Continuous evolution into a 21st-century digital center of excellence with high-speed LAN networking, smart interactive teaching boards, digital knowledge repositories, and being designated as an official GSEB Board Examination Assessment Hub.', '["Upgraded computer labs with 80+ networked desktop units and gigabit optical fiber connectivity.", "Official Board Examination Assessment and Evaluation Center for Banaskantha GSEB exams.", "Integration of interactive digital pedagogy, Adarsh Public Library automation, and solar eco-initiatives."]'::jsonb, 'Sparkles', '/images/physics.jpg', 6, 'published')
INSERT INTO public.gallery (id, title, caption, category, image_url, sort_order, status) VALUES
('g1', 'Physics & Science Laboratory Practical Session', 'Students conducting electricity and mechanics practicals on calibrated physics benches in the Science complex.', 'labs', '/images/physics.jpg', 1, 'published'),
('g2', 'A.N. Musa Modern Computer Centre Workstations', 'Interactive computer science lab equipped with networked PCs and modern programming suites.', 'labs', '/images/computer.jpg', 2, 'published'),
('g3', 'SKM High School Historic Main Building & Verandahs', 'Front facade of SKM High School established in 1956 by Sarvoday Kelavani Mandal, Kanodar.', 'campus', '/images/building.jpg', 3, 'published'),
('g4', 'Adarsh Public & School Central Library Reading Hall', 'Spacious reading hall and cataloged book almirahs providing literature and competitive exam resources.', 'campus', '/images/library.jpg', 4, 'published'),
('g5', 'School Sports Ground & Volleyball Arena', 'Expansive open playground surrounded by lush green trees for daily physical training and sports matches.', 'sports', '/images/playground.jpg', 5, 'published'),
('g6', 'Merit Award Ceremony & Board Toppers Felicitation', 'Sarvoday Kelavani Mandal trustees awarding gold medals and scholarships to HSC toppers.', 'cultural', 'https://images.unsplash.com/photo-1523580494863-6f3031224c94?auto=format&fit=crop&w=800&q=80', 6, 'published')
INSERT INTO public.faqs (id, question, answer, category, sort_order, status) VALUES
('faq_1', 'What is the admission procedure for Secondary (Std 8-10) and Higher Secondary (Std 11-12)?', 'Admissions begin in May/June for the upcoming academic year. For Secondary classes (Std 8-10), admissions are granted based on previous grade marksheet and School Leaving Certificate (L.C.). For Higher Secondary Science and General streams, admissions are allotted based on GSEB Std 10th S.S.C. board marks and merit counseling. Online admission inquiry forms can also be submitted via this website.', 'admissions', 1, 'published'),
('faq_2', 'What academic streams are available in the Higher Secondary Section?', 'SKM High School offers: 1) Higher Secondary Science Stream (Group A - Maths/Engineering & Group B - Biology/Medical) with advanced lab practicals and GUJCET guidance; 2) Higher Secondary General Stream (Commerce & Arts); and 3) Vocational Life-Skill programs including Home Science for girls and Electrical/Technical workshops for boys.', 'academics', 2, 'published'),
('faq_3', 'What are the school timings and shifts?', 'The school operates two well-organized sessions: Morning Shift (7:30 AM to 1:15 PM) primarily for Higher Secondary and Science practical batches, and General Shift (11:30 AM to 5:30 PM) for Secondary classes. Administrative and office desks operate from 8:00 AM to 2:00 PM Monday through Saturday.', 'general', 3, 'published'),
('faq_4', 'Are there scholarship programs available for deserving and underprivileged students?', 'Yes. Sarvoday Kelavani Mandal, along with the Dawoodi Bohra Welfare Trust and R.K. Palasara Pariwar, provides multiple merit-cum-means scholarships, fee waivers for meritorious students, and free textbooks/uniforms for underprivileged scholars to ensure no child is denied education.', 'admissions', 4, 'published'),
('faq_5', 'What safety, laboratory, and campus amenities exist for girl students?', 'SKM High School is deeply committed to women''s empowerment. We feature dedicated Home Science labs, separate clean sanitation facilities, full CCTV coverage, female faculty mentorship, and specialized self-defense and guidance counseling for female students.', 'facilities', 5, 'published'),
('faq_6', 'How can parents track official school announcements, timetables, and teacher meetings?', 'Parents and students can access the live Announcements & Circulars section on this portal for official circulars, exam timetables, and board notices, or contact our faculty and administrative desk during office hours.', 'general', 6, 'published')
INSERT INTO public.achievements (id, title, year, category, awardee, rank_or_percentile, description, badge, metric, status) VALUES
('a1', 'GSEB Std 12th HSC Science Stream State & District Top Rank', '2025–2026', 'board', 'Master Soham Patel & Kum. Aafreen Mansuri', '99.85 Percentile (PR)', 'Secured District 1st Rank with 100/100 in Physics and Mathematics, qualifying directly for government medical and top engineering institutions.', 'State Merit Rank', '99.85 PR', 'published'),
('a2', '100% Result in GSEB S.S.C. Class 10th Board Examination', '2025–2026', 'board', 'Secondary Section Batch of 2026', '100% Pass Percentage', 'Out of 280 registered candidates, 100% passed with 62 students achieving A1 & A2 distinction grades.', '100% Pass Rate', '62 A1/A2 Grades', 'published'),
('a3', 'State Science Fair 1st Prize: Smart Solar Irrigation & AI IoT Model', '2025', 'science', 'SKM Innovation & Robotics Club', 'State 1st Prize Winner', 'Developed an automated solar-powered soil moisture and drip irrigation device displayed at the Gujarat State Council of Educational Research.', 'State Innovation Award', '1st in Gujarat', 'published'),
('a4', 'Bharat Scouts & Guides: Rashtrapati & Rajya Puraskar Honors', '2024–2025', 'scouts', '14 SKM Scout & Guide Cadets', 'Governor Award Felicitation', 'Honored by the Honorable Governor of Gujarat at Raj Bhavan for exemplary national discipline, disaster rescue drills, and community service.', 'Rajya Puraskar', '14 Cadets Honored', 'published'),
('a5', 'Banaskantha District Inter-School Volleyball Championship Gold', '2025', 'sports', 'SKM High School Senior Volleyball Team', 'District Champions (Gold)', 'Defeated 32 participating district teams in undefeated straight sets to lift the prestigious District Collector Rolling Trophy.', 'District Champions', 'Undefeated Gold', 'published'),
('a6', 'Alumni Excellence: 150+ Doctors, 400+ Engineers & Civil Servants', '1956–2026', 'alumni', 'SKM Global Alumni Fraternity', 'Global Impact Legacy', 'Proud alumni contributing globally across USA, UK, Gulf, and across India as renowned surgeons, AI researchers, administrators, and philanthropists.', 'Alumni Distinction', '25,000+ Worldwide', 'published')
INSERT INTO public.staff (id, name, role, designation, department, qualifications, experience_years, subjects, achievements, email, photo_url, is_lead, sort_order, status) VALUES
('t1', 'Dr. Arvindkumar K. Patel', 'Principal & Head of Institution', 'Principal', 'administration', 'Ph.D. in Educational Leadership, M.Sc. (Physics), M.Ed.', '28+ Years', '["Institutional Administration", "Higher Secondary Physics Guidance", "Board Exam Co-ordination"]'::jsonb, 'State Best Principal Award Nominee, GSEB District Center Superintendent (15+ Years)', 'principal@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', true, 1, 'published'),
