('t5', 'Shri Hareshbhai N. Chaudhary', 'Senior Lecturer in Mathematics', 'Lecturer in Advanced Mathematics', 'science', 'M.Sc. (Applied Mathematics), B.Ed.', '18+ Years', '["HSC Mathematics (Group A)", "Calculus & Vectors", "JEE Main Math Specialist"]'::jsonb, 'Ranked Top Mathematics Faculty in North Gujarat GSEB District Zone', 'maths@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', false, 5, 'published'),
('t6', 'Shri Dilipkumar R. Shah', 'HOD - Commerce & General Stream', 'Senior Lecturer in Accountancy', 'commerce', 'M.Com. (Advanced Accountancy), B.Ed., C.A. (Inter)', '22+ Years', '["Elements of Accounts", "Business Administration (B.A.)", "CA Foundation Orientation"]'::jsonb, '15+ Students scored 100/100 in GSEB HSC Board Accountancy', 'commerce@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', true, 6, 'published'),
('t7', 'Smt. Farhanabanu I. Mansuri', 'Senior Lecturer in Economics & Statistics', 'Lecturer in Economics', 'commerce', 'M.A. (Economics), M.Ed.', '16+ Years', '["Indian Economics", "Business Statistics", "Commercial Communication"]'::jsonb, 'Keynote Speaker at North Gujarat Commerce Teachers Forum', 'economics@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', false, 7, 'published'),
('t8', 'Shri Pravinbhai G. Parmar', 'HOD - Secondary School Section', 'Senior Secondary Master', 'secondary', 'M.A. (Gujarati Literature), B.Ed.', '25+ Years', '["Secondary Gujarati (First Language)", "Sanskrit Grammar", "Cultural Activities"]'::jsonb, 'District Best Teacher Awardee, Chief Cultural Director for Sarvoday Mandal', 'secondary@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', true, 8, 'published'),
('t9', 'Shri Altafhussain K. Qureshi', 'Director - A.N. Musa Computer Centre', 'Head of IT & Digital Pedagogy', 'vocational', 'M.C.A., B.Sc. (Computer Science), PGDCA', '15+ Years', '["Computer Science (Std 9–12)", "Python & C Programming", "LAN Networking & Digital Skills"]'::jsonb, 'Established campus-wide optical fiber network & 80+ terminal lab setup', 'itlab@skmkanodar.org', 'https://images.unsplash.com/photo-1577896851231-70ef18881754?w=400&auto=format&fit=crop&q=80', false, 9, 'published'),
