INSERT INTO public.events (id, title, description, event_date, start_time, end_time, location, category, cover_image, status) VALUES
('evt_1', '70th Institutional Foundation Day & Sarvoday Sneh Milan', 'Annual gathering celebrating 70 glorious years since May 28, 1956 with patron families, alumni scholars, and student science exhibitions.', '2026-05-28', '09:00 AM', '01:30 PM', 'Late Mamjibhai Mukhi Memorial Auditorium', 'Institutional', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1000&auto=format&fit=crop&q=80', 'published'),
('evt_2', 'North Gujarat Inter-School STEM & Robotics Fair', 'Hands-on project showcases from Class 9-12 Science students including smart agricultural sensors and physics models.', '2026-09-15', '10:00 AM', '04:00 PM', 'A.N. Musa Computer Centre & Physics Labs', 'Academic', 'https://images.unsplash.com/photo-1581093458791-9f3c3900df4b?w=1000&auto=format&fit=crop&q=80', 'published'),
('evt_3', 'Khel Mahakumbh District Athletic Meet 2026', 'District level track and field, volleyball tournaments and kabaddi matches hosted on the SKM campus athletic grounds.', '2026-10-10', '08:00 AM', '05:00 PM', 'SKM Sports Complex & Pavilion', 'Sports', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=1000&auto=format&fit=crop&q=80', 'published')
INSERT INTO public.documents (id, title, category, description, file_url, file_name, file_size, download_count, status) VALUES
('doc_1', 'Academic Prospectus & Admission Guidelines 2026–27', 'Prospectus', 'Complete institutional prospectus including stream subjects, eligibility rules, fee concessions, and scholarship criteria.', 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf', 'SKM_Prospectus_2026-27.pdf', '2.4 MB', 142, 'published'),
('doc_2', 'GSEB Secondary & Higher Secondary Annual Academic Calendar', 'Timetable', 'Official schedule of term dates, internal unit evaluations, semester preliminary exams, and vacation periods.', 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf', 'GSEB_Academic_Calendar_2026.pdf', '1.1 MB', 320, 'published')
